var scene=UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene();
var actors=UnityEngine.Object.FindObjectsByType<AthenHill.ActorAnimation>();
var report=new System.Collections.Generic.List<object>();
foreach(var actor in actors) {
 var renderers=new System.Collections.Generic.List<object>(); long triangles=0;
 foreach(var r in actor.GetComponentsInChildren<UnityEngine.Renderer>(true)) {
  var skin=r as UnityEngine.SkinnedMeshRenderer;
  var filter=r.GetComponent<UnityEngine.MeshFilter>();
  var mesh=skin ? skin.sharedMesh : filter ? filter.sharedMesh : null;
  long count=0; if(mesh) for(int s=0;s<mesh.subMeshCount;s++) count+=(long)mesh.GetIndexCount(s)/3;
  triangles+=count;
  renderers.Add(new { name=r.name,type=r.GetType().Name,active=r.gameObject.activeInHierarchy,enabled=r.enabled,shadows=r.shadowCastingMode.ToString(),receiveShadows=r.receiveShadows,triangles=count,mesh=mesh?mesh.name:null });
 }
 report.Add(new { name=actor.name,triangles=triangles,renderers=renderers });
}
return new {scene=scene.path,dirty=scene.isDirty,actors=report};
